  mkLRule (mkC StD (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []))
          (mkC StD (mkS [S0;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 4.
