Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1LB_1LA1LC_1RC0RD_0LB1RD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LB_1LA1LC_1RC0RD_0LB1RD
  | 0, 1 => iarm0_1_1RB1LB_1LA1LC_1RC0RD_0LB1RD
  | 1, 0 => iarm1_0_1RB1LB_1LA1LC_1RC0RD_0LB1RD
  | 1, 1 => iarm1_1_1RB1LB_1LA1LC_1RC0RD_0LB1RD
  | _, _ => iarm0_0_1RB1LB_1LA1LC_1RC0RD_0LB1RD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB1LB_1LA1LC_1RC0RD_0LB1RD : LRule :=
  mkLRule (mkC StD (mkS [S0;S1] [S0;S1] 1 0 []) S0 (mkS [] [] 0 0 []))
          (mkC StD (mkS [S1;S1] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 [])) 4 10.
Definition ch_farm1_0_1RB1LB_1LA1LC_1RC0RD_0LB1RD : list rstep := [RB (SWin 2);RB (SCycL 2 0);RB (SWinL 6);RB (SCycR 2);RB (SWin 2)].
