Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1LB_1LC0RD_0RC1LA_0LB1RD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LB_1LC0RD_0RC1LA_0LB1RD
  | 0, 1 => iarm0_1_1RB1LB_1LC0RD_0RC1LA_0LB1RD
  | _, _ => iarm0_0_1RB1LB_1LC0RD_0RC1LA_0LB1RD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

