          (mkC StD (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S0;S1;S1]) S0 (mkS [] [] 0 0 [])) 6 8.
Definition ch_iarm0_1_1RB1LB_1LC0RD_1LA0RB_0LB1RD : list rstep := [RB (SWin 3);RB (SCycL 3 0);RB (SWin 2);RB (SCycR 3);RB (SWin 3)].
