(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB1LB_1LC0RD_1LA0RB_0LB1RD : NeverQuasiHaltsTr tm_1RB1LB_1LC0RD_1LA0RB_0LB1RD.
Proof.
  apply (boardph_neverqhtr tm_1RB1LB_1LC0RD_1LA0RB_0LB1RD pins_1RB1LB_1LC0RD_1LA0RB_0LB1RD FAM 2
                           iarm_1RB1LB_1LC0RD_1LA0RB_0LB1RD 1 1
                           farm_1RB1LB_1LC0RD_1LA0RB_0LB1RD 1 1
                           fm1_1RB1LB_1LC0RD_1LA0RB_0LB1RD fm2_1RB1LB_1LC0RD_1LA0RB_0LB1RD 1 vis_1RB1LB_1LC0RD_1LA0RB_0LB1RD
                           [2] 1 12).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 1; vm_compute; reflexivity. }
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB1LB_1LC0RD_1LA0RB_0LB1RD.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - exact boot_1RB1LB_1LC0RD_1LA0RB_0LB1RD.
  - lia.
  - exact iarm_sound_1RB1LB_1LC0RD_1LA0RB_0LB1RD.
  - exact iarm_lhs_1RB1LB_1LC0RD_1LA0RB_0LB1RD.
  - exact iarm_rhs_1RB1LB_1LC0RD_1LA0RB_0LB1RD.
  - exact iarm_cb_1RB1LB_1LC0RD_1LA0RB_0LB1RD.
  - lia.
  - lia.
  - exact farm_sound_1RB1LB_1LC0RD_1LA0RB_0LB1RD.
  - exact farm_lhs_1RB1LB_1LC0RD_1LA0RB_0LB1RD.
  - exact farm_rhs_1RB1LB_1LC0RD_1LA0RB_0LB1RD.
  - exact farm_cb_1RB1LB_1LC0RD_1LA0RB_0LB1RD.
  - exact vis_ok_1RB1LB_1LC0RD_1LA0RB_0LB1RD.
Qed.

