  mkLRule (mkC StD (mkS [S1;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []))
          (mkC StD (mkS [S0;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 2.
Definition ch_iarm0_0_1RB1LB_1LC0RD_1LA1LA_0LB1RD : list rstep := [RB (SWin 2)].
Lemma ok_iarm0_0_1RB1LB_1LC0RD_1LA1LA_0LB1RD :
  check_arm tm false true rules iarm0_0_1RB1LB_1LC0RD_1LA1LA_0LB1RD
            ch_iarm0_0_1RB1LB_1LC0RD_1LA1LA_0LB1RD = true.
Proof. vm_compute. reflexivity. Qed.

