Lemma farm_sound_1RB1LB_1LC0RD_1LA1LA_0LC1RD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 -> RuleSound tm true true (farm_1RB1LB_1LC0RD_1LA1LA_0LC1RD r ph).
