Lemma farm_rhs_1RB1LB_1LC0RD_1LA1LA_0LC1RD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  lr_rhs (farm_1RB1LB_1LC0RD_1LA1LA_0LC1RD r ph)
    = cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_1RB1LB_1LC0RD_1LA1LA_0LC1RD r ph)
                      (astride 1 1 r) (fm2_1RB1LB_1LC0RD_1LA1LA_0LC1RD r ph)
                      (f_to (fam_fill FAM ph))
