  d < fm_b FAM - 1 -> r < 1 + 1 ->
  RuleSound tm (negb (fm_left FAM)) (fm_left FAM) (iarm_1RB1LB_1LC0RD_1LA1LB_0LA1RD d r).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LB_1LC0RD_1LA1LB_0LA1RD | exact ok_iarm0_0_1RB1LB_1LC0RD_1LA1LB_0LA1RD]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LB_1LC0RD_1LA1LB_0LA1RD | exact ok_iarm0_1_1RB1LB_1LC0RD_1LA1LB_0LA1RD]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

