(** The machine-level theorem, at the INSTRUCTION level: the board above
    runs on the machine wrapped at the pins, and
    [LadderCheckTr.boardph_neverqhtr] turns it into [NeverQuasiHaltsTr] of
    the machine itself. *)
Theorem nqhtr_1RB1LB_1LC0RD_1LA1LB_0LC1RD : NeverQuasiHaltsTr tm_1RB1LB_1LC0RD_1LA1LB_0LC1RD.
Proof.
  apply (boardph_neverqhtr tm_1RB1LB_1LC0RD_1LA1LB_0LC1RD pins_1RB1LB_1LC0RD_1LA1LB_0LC1RD FAM 2
